  "Cards you make are kept here, ready to play, change or send again.": "Os cartões que você faz ficam aqui, prontos para tocar, editar ou enviar de novo.",
  "Cards friends send you are kept here, so you can watch them again.": "Os cartões que os amigos te mandam ficam aqui, para você assistir de novo.",
