  "Wishing you a blessed Eid full of feasts, family and happy moments.": "Desejo um Eid abençoado, cheio de banquetes, família e momentos felizes.",
  "Eid Mubarak, my friend! Save some biryani for me.": "Eid Mubarak, meu amigo! Guarda um pouco de biryani para mim.",
  "May this Eid bring you peace, joy and every blessing you wish for.": "Que este Eid traga paz, alegria e todas as bênçãos que você deseja.",
  "Eid Mubarak! Wishing you and your family peace, joy and blessings.": "Eid Mubarak! Desejo a você e à sua família paz, alegria e bênçãos.",
  "Eid Mubarak! Wishing you and your family a peaceful, joyful celebration.": "Eid Mubarak! Desejo a você e à sua família uma comemoração tranquila e alegre.",
  "May this Eid bring you happiness and success. Eid Mubarak!": "Que este Eid traga felicidade e sucesso. Eid Mubarak!",
  "Eid Mubarak! May your heart be as full as this sky tonight.": "Eid Mubarak! Que seu coração esteja tão cheio quanto este céu hoje.",
  "Wishing you nine nights of devotion, dance and happiness.": "Desejo nove noites de devoção, dança e felicidade.",
  "Happy Navratri! You are the strength of our family, every day of the year.": "Feliz Navratri! Você é a força da nossa família, todos os dias do ano.",
  "May Maa Durga bless you with good health, peace and happiness.": "Que Maa Durga te abençoe com saúde, paz e felicidade.",
  "Happy Navratri! Thank you for teaching us the prayers and the stories.": "Feliz Navratri! Obrigado por nos ensinar as orações e as histórias.",
  "May the Goddess bless you with good health and joy this Navratri.": "Que a Deusa te abençoe com saúde e alegria neste Navratri.",
  "Happy Navratri, my love. Let’s dance the garba together all nine nights.": "Feliz Navratri, meu amor. Vamos dançar garba juntos nas nove noites.",
