  "Dance your heart out at garba tonight. Happy Navratri!": "Dance com o coração no garba hoje. Feliz Navratri!",
  "Happy Navratri! Ready for nine nights of garba and dandiya?": "Feliz Navratri! Pronto para nove noites de garba e dandiya?",
  "May Maa Durga bless you with all the strength you need. Happy Navratri!": "Que Maa Durga te dê toda a força de que você precisa. Feliz Navratri!",
