  "Wishing you nine nights of joy, devotion and celebration.": "Desejo nove noites de alegria, devoção e festa.",
  "Happy Navratri! See you on the garba floor, my friend.": "Feliz Navratri! Te vejo na pista de garba, meu amigo.",
  "May the nine nights bring you nine reasons to smile.": "Que as nove noites tragam nove motivos para sorrir.",
  "Happy Navratri! May the Goddess of learning bless you always.": "Feliz Navratri! Que a Deusa do saber te abençoe sempre.",
  "Happy Navratri! May this festival bring you strength and success.": "Feliz Navratri! Que esta festa traga força e sucesso.",
  "Wishing you and your family a blessed and joyful Navratri.": "Desejo a você e à sua família um Navratri abençoado e alegre.",
  "Happy Navratri! May every night of the festival bring you joy.": "Feliz Navratri! Que cada noite da festa traga alegria.",
  "Wishing you pandal hopping, bhog and happy days with loved ones.": "Desejo passeios pelos pandals, bhog e dias felizes com quem você ama.",
  "Shubho Durga Puja! You are the strength of our family, just like Maa.": "Shubho Durga Puja! Você é a força da nossa família, assim como Maa.",
  "Wishing you a joyful Pujo, good health and lots of happy days.": "Desejo um Pujo alegre, saúde e muitos dias felizes.",
  "Shubho Durga Puja! Your blessings make every Pujo complete.": "Shubho Durga Puja! Suas bênçãos deixam todo Pujo completo.",
  "Wishing you good health and a peaceful, joyful Pujo.": "Desejo saúde e um Pujo tranquilo e alegre.",
  "Shubho Durga Puja, my love. Pandal hopping is always better with you.": "Shubho Durga Puja, meu amor. Passear pelos pandals é sempre melhor com você.",
  "May Maa Durga bless our home with love and happiness.": "Que Maa Durga abençoe nossa casa com amor e felicidade.",
  "Shubho Durga Puja! May Maa bless you with courage and success.": "Shubho Durga Puja! Que Maa te abençoe com coragem e sucesso.",
