  "Shubho Durga Puja! May Maa bless you with every happiness.": "Shubho Durga Puja! Que Maa te abençoe com toda a felicidade.",
  "A thread of love, a promise of care. Happy Raksha Bandhan!": "Um fio de amor, uma promessa de cuidado. Feliz Raksha Bandhan!",
  "Happy Raksha Bandhan! Thank you for always protecting me, even from myself.": "Feliz Raksha Bandhan! Obrigado por sempre me proteger, até de mim mesmo.",
  "You annoy me, you defend me and you know all my secrets. Happy Rakhi!": "Você me irrita, me defende e sabe todos os meus segredos. Feliz Rakhi!",
  "No distance can loosen this thread. Happy Raksha Bandhan!": "Nenhuma distância afrouxa este fio. Feliz Raksha Bandhan!",
  "Happy Raksha Bandhan! You have always been like my own sibling.": "Feliz Raksha Bandhan! Você sempre foi como um irmão para mim.",
  "Wishing you a Rakhi full of sweets and happy memories.": "Desejo um Rakhi cheio de doces e lembranças felizes.",
