  "Happy Raksha Bandhan! Thank you for the blessings you give us on every Rakhi.": "Feliz Raksha Bandhan! Obrigado pelas bênçãos que você nos dá em cada Rakhi.",
  "Happy Raksha Bandhan! Seeing you look out for each other fills our hearts.": "Feliz Raksha Bandhan! Ver vocês cuidando um do outro enche nosso coração.",
  "Happy Raksha Bandhan to you and your siblings, my love. We are lucky to have them.": "Feliz Raksha Bandhan para você e seus irmãos, meu amor. Temos sorte de tê-los.",
  "Happy Raksha Bandhan! You’re the sibling I got to choose.": "Feliz Raksha Bandhan! Você é o irmão que eu pude escolher.",
