  "Happy Raksha Bandhan! May the bonds you cherish grow stronger every year.": "Feliz Raksha Bandhan! Que os laços que você ama fiquem mais fortes a cada ano.",
  "Wishing you a Bhai Dooj full of love, sweets and blessings.": "Desejo um Bhai Dooj cheio de amor, doces e bênçãos.",
  "Happy Bhai Dooj! I pray for your long life and happiness, today and always.": "Feliz Bhai Dooj! Rezo por sua vida longa e feliz, hoje e sempre.",
