  "Happy Karwa Chauth! Your love for each other inspires all of us.": "Feliz Karwa Chauth! O amor de vocês inspira todos nós.",
  "Happy Karwa Chauth! Your years of love are the best blessing for our family.": "Feliz Karwa Chauth! Seus anos de amor são a melhor bênção da nossa família.",
