  "Welcoming Bappa home is sweetest when it’s with you.": "Receber Bappa em casa é mais doce quando é com você.",
  "Happy Ganesh Chaturthi! May Bappa bless you with wisdom and success.": "Feliz Ganesh Chaturthi! Que Bappa te abençoe com sabedoria e sucesso.",
  "May Bappa clear every obstacle on your path. Ganpati Bappa Morya!": "Que Bappa tire todos os obstáculos do seu caminho. Ganpati Bappa Morya!",
  "Happy Ganesh Chaturthi! Don’t eat all the modaks before the aarti this time.": "Feliz Ganesh Chaturthi! Desta vez não coma todos os modaks antes da aarti.",
