  "May Bappa bless you with new beginnings and success.": "Que Bappa te abençoe com novos começos e sucesso.",
  "Happy Ganesh Chaturthi! May Lord Ganesha, the giver of wisdom, bless you always.": "Feliz Ganesh Chaturthi! Que o Senhor Ganesha, que dá a sabedoria, te abençoe sempre.",
  "Happy Ganesh Chaturthi! May Bappa bring you success in every new beginning.": "Feliz Ganesh Chaturthi! Que Bappa traga sucesso em cada novo começo.",
  "Wishing you and your family a blessed Ganesh Chaturthi.": "Desejo a você e à sua família um Ganesh Chaturthi abençoado.",
  "Happy Ganesh Chaturthi! May Bappa bless you with every happiness.": "Feliz Ganesh Chaturthi! Que Bappa te abençoe com toda a felicidade.",
  "Two hearts, one journey. Congratulations on your wedding!": "Dois corações, uma jornada. Parabéns pelo casamento!",
  "Your love story is the one we all look up to. Congratulations on this beautiful day!": "A história de amor de vocês é a que todos admiramos. Parabéns por este dia lindo!",
  "Thank you for blessing this wedding with your love. It means the world to us.": "Obrigado por abençoar este casamento com seu amor. Isso significa o mundo para nós.",
  "Today I married my best friend. Here’s to forever, my love.": "Hoje me casei com meu melhor amigo. Um brinde ao para sempre, meu amor.",
  "I can’t wait to spend every day of my life with you. Happy wedding day!": "Mal posso esperar para passar todos os dias da minha vida com você. Feliz dia do casamento!",
  "Congratulations, my dear! May your married life be full of love and laughter.": "Parabéns, querido(a)! Que sua vida de casado seja cheia de amor e risadas.",
  "We are so proud of you both. Wishing you a lifetime of happiness together.": "Temos muito orgulho de vocês dois. Desejo uma vida inteira de felicidade juntos.",
  "Congratulations! I’m so happy for you, and I get a new family member too.": "Parabéns! Estou muito feliz por você, e ainda ganho alguém novo na família.",
  "From sharing a room to seeing you get married: I love you. Happy married life!": "De dividir o quarto a ver você se casar: te amo. Felicidades aos noivos!",
  "Congratulations to the lovely couple! Wishing you a lifetime of happiness.": "Parabéns ao lindo casal! Desejo uma vida inteira de felicidade.",
  "Wishing you both love, laughter and a home full of joy.": "Desejo aos dois amor, risadas e uma casa cheia de alegria.",
  "Congratulations, my friend! You two are perfect together.": "Parabéns, meu amigo! Vocês dois são perfeitos juntos.",
  "Wishing you a lifetime of adventures, inside jokes and love.": "Desejo uma vida inteira de aventuras, piadas internas e amor.",
  "Congratulations on your wedding! Wishing you both a lifetime of happiness.": "Parabéns pelo casamento! Desejo aos dois uma vida inteira de felicidade.",
  "Congratulations on your wedding! Wishing you both a wonderful life together.": "Parabéns pelo casamento! Desejo aos dois uma vida maravilhosa juntos.",
  "Best wishes to you both on your new journey together.": "Felicidades aos dois nesta nova jornada juntos.",
  "Congratulations! May your love grow brighter every year.": "Parabéns! Que o amor de vocês brilhe mais a cada ano.",
  "A tiny new star has arrived. Congratulations to the proud family!": "Uma estrelinha nova chegou. Parabéns à família orgulhosa!",
  "Congratulations, new grandparents! This little one is so lucky to have you.": "Parabéns, novos avós! Este pequenino tem muita sorte de ter vocês.",
  "Congratulations, great-grandparents! Our family keeps growing with love.": "Parabéns, bisavós! Nossa família não para de crescer com amor.",
  "Thank you for our beautiful baby. I love you more than ever.": "Obrigado pelo nosso bebê lindo. Te amo mais do que nunca.",
  "Our family just got bigger, and my heart did too.": "Nossa família ficou maior, e meu coração também.",
  "Congratulations on becoming a parent! We are so proud of you.": "Parabéns por se tornar pai ou mãe! Temos muito orgulho de você.",
  "Watching you hold your baby is a moment we will never forget.": "Ver você segurando seu bebê é um momento que nunca vamos esquecer.",
  "Congratulations! I can’t wait to spoil my new niece or nephew.": "Parabéns! Mal posso esperar para mimar meu sobrinho ou sobrinha.",
  "You’re going to be an amazing parent. So happy for you!": "Você vai ser um pai ou mãe incrível. Muito feliz por você!",
  "Congratulations on the new arrival! Wishing your little one health and happiness.": "Parabéns pela chegada! Desejo saúde e felicidade ao pequenino.",
  "Welcome to the family, little one! We can’t wait to meet you.": "Bem-vindo à família, pequenino! Mal podemos esperar para te conhecer.",
  "Congratulations, my friend! Your baby is lucky to have you.": "Parabéns, meu amigo! Seu bebê tem sorte de ter você.",
  "Welcome to the world, little one. Your parents are the best.": "Bem-vindo ao mundo, pequenino. Seus pais são os melhores.",
  "Congratulations on your little one! Wishing your family endless joy.": "Parabéns pelo pequenino! Desejo alegria sem fim à família.",
  "Congratulations on your new arrival! Wishing you joy and plenty of sleep.": "Parabéns pela chegada! Desejo alegria e muitas horas de sono.",
  "Welcome to the little one! Wishing your family all the happiness.": "Bem-vindo, pequenino! Desejo toda a felicidade à família.",
  "Congratulations! May your little one bring you endless joy.": "Parabéns! Que seu pequenino traga alegria sem fim.",
  "New walls, new doors, same wonderful you. Congratulations on your new home!": "Paredes novas, portas novas, e você maravilhoso(a) como sempre. Parabéns pela casa nova!",
  "Congratulations on the new home! I can’t wait to fill it with family visits.": "Parabéns pela casa nova! Mal posso esperar para enchê-la de visitas da família.",
  "May your new home be as warm as the one you gave us.": "Que sua casa nova seja tão acolhedora quanto a que você nos deu.",
  "Congratulations on your new home! May it be blessed with peace and happiness.": "Parabéns pela casa nova! Que ela seja abençoada com paz e felicidade.",
  "Our first home together. Here’s to a lifetime of memories inside these walls.": "Nossa primeira casa juntos. Um brinde a uma vida de lembranças entre estas paredes.",
  "Home is wherever you are, and now it has a front door too.": "Lar é onde você está, e agora ele tem porta de entrada também.",
  "Congratulations on your new home! We’re so proud of you.": "Parabéns pela casa nova! Temos muito orgulho de você.",
  "May your new home bring you comfort, joy and success.": "Que sua casa nova traga conforto, alegria e sucesso.",
  "Congratulations on the new place! I’m claiming the guest room.": "Parabéns pelo lugar novo! O quarto de hóspedes é meu.",
  "Your own home at last! So happy for you.": "Sua própria casa, finalmente! Muito feliz por você.",
  "Congratulations on your new home! May it bring your family much happiness.": "Parabéns pela casa nova! Que ela traga muita felicidade à sua família.",
