  "Congratulations on the new home! When’s the party?": "Parabéns pela casa nova! Quando é a festa?",
  "May your new home be full of good food, good friends and good times.": "Que sua casa nova seja cheia de comida boa, bons amigos e bons momentos.",
  "Congratulations on your new home! Wishing you many happy days in it.": "Parabéns pela casa nova! Desejo muitos dias felizes nela.",
