  "Out of every sky I've seen, you're still the brightest light in mine.": "De todos os céus que já vi, você ainda é a luz mais brilhante do meu.",
  "I love that home stopped being a place the day it became you.": "Adoro que lar deixou de ser um lugar no dia em que virou você.",
  "Every firework fades. What I feel for you only gets louder.": "Todo fogo se apaga. O que sinto por você só fica mais forte.",
