  "I love you because with you, even silence feels like…": "Te amo porque com você até o silêncio parece…",
  "Warning: you make my heart burst louder than a thousand-wala.": "Atenção: você faz meu coração estourar mais alto que mil bombinhas.",
  "Are you a sparkler? You light me up every time you smile.": "Você é uma estrelinha? Me ilumina toda vez que sorri.",
