  "Your hug is my favourite place to be.": "Seu abraço é meu lugar favorito.",
  "With you, every day is a little Diwali.": "Com você, todo dia é um pequeno Diwali.",
  "I love the little things you do, like…": "Adoro as pequenas coisas que você faz, como…",
