  "Light the way": "Ilumine o caminho",
  "Light crackers to see in the dark. Follow the clues: their tracks, a dropped bell, their cart.": "Acenda fogos para enxergar no escuro. Siga as pistas: as pegadas, um sino derrubado, a carroça deles.",
  "Bring it home": "Traga de volta",
