  "The Silver Peacock Lamp": "A Lamparina do Pavão de Prata",
  "Thieves took the temple’s silver peacock lamp. Follow the jasmine trail and bring it back": "Ladrões levaram a lamparina do pavão de prata do templo. Siga a trilha de jasmim e traga-a de volta",
  "Lamps for Madurai": "Lamparinas para Madurai",
  "Madurai’s temple street is full of lamps tonight, and the silver peacock lamp is the brightest.": "A rua do templo de Madurai está cheia de lamparinas hoje, e a do pavão de prata é a mais brilhante.",
  "The peacock lamp is gone!": "A lamparina do pavão sumiu!",
  "Thieves have taken the silver peacock lamp and slipped into the flower market.": "Ladrões levaram a lamparina do pavão de prata e fugiram para o mercado de flores.",
  "Follow the jasmine": "Siga o jasmim",
  "Light crackers to see in the dark. Follow the clues: jasmine petals, an anklet bell, a flower basket.": "Acenda fogos para enxergar no escuro. Siga as pistas: pétalas de jasmim, um guizo de tornozeleira, um cesto de flores.",
  "Bring it back": "Traga de volta",
  "Find the peacock lamp and carry it back to the temple steps before the lamps are lit.": "Encontre a lamparina do pavão e leve-a de volta aos degraus do templo antes de acenderem as lamparinas.",
  "🦚 The silver peacock lamp is gone! Light a cracker by the dark patch to find the jasmine trail": "🦚 A lamparina do pavão de prata sumiu! Acenda um fogo perto do trecho escuro para achar a trilha de jasmim",
  "🚨 Seth-ji thinks YOU are the thief! Run the peacock lamp to the temple steps 🛕": "🚨 O Seth-ji acha que o ladrão é VOCÊ! Leve a lamparina do pavão correndo até os degraus do templo 🛕",
  "The peacock lamp is home!": "A lamparina do pavão voltou para casa!",
  "The temple’s lamps shine on the silver peacock again 🪔": "As lamparinas do templo brilham de novo sobre o pavão de prata 🪔",
  "You followed the jasmine petals, the anklet bell and the flower basket, and brought the silver peacock lamp back to the temple steps.": "Você seguiu as pétalas de jasmim, o guizo e o cesto de flores e levou a lamparina do pavão de prata de volta aos degraus do templo.",
  "I brought the silver peacock lamp home to the temple in Fireworks Street!": "Levei a lamparina do pavão de prata de volta ao templo na Rua dos Fogos!",
  "Light up the jasmine trail": "Ilumine a trilha de jasmim",
  "Jasmine petals! The thieves ran up the street with flowers on their feet": "Pétalas de jasmim! Os ladrões subiram a rua com flores nos pés",
  "A silver anklet bell, dropped on the run. They went this way": "Um guizo de tornozeleira de prata, derrubado na fuga. Foram por aqui",
  "Search the flower basket": "Revistar o cesto de flores",
  "Under the jasmine in a flower-seller’s basket: the silver peacock lamp!": "Debaixo do jasmim no cesto de uma florista: a lamparina do pavão de prata!",
  "The Golden Deepam Lamp": "A Lamparina Dourada do Deepam",
  "Thieves took the great lamp for the Deepam. Follow the oil drips and bring it back for the lighting": "Ladrões levaram a grande lamparina do Deepam. Siga as gotas de óleo e traga-a de volta para o acendimento",
  "The great lamp": "A grande lamparina",
  "Tonight the great golden lamp is to be lit for Karthigai Deepam, for the whole town to see.": "Hoje à noite a grande lamparina dourada vai ser acesa no Karthigai Deepam, para a cidade inteira ver.",
  "The Deepam lamp is gone!": "A lamparina do Deepam sumiu!",
  "Thieves have taken the golden lamp, still dripping with oil, into the dark streets.": "Ladrões levaram a lamparina dourada, ainda pingando óleo, pelas ruas escuras.",
  "Follow the oil": "Siga o óleo",
  "Light crackers to see in the dark. Follow the clues: oil drips, a dropped bundle of wicks, the oil merchant’s cart.": "Acenda fogos para enxergar no escuro. Siga as pistas: gotas de óleo, um maço de pavios derrubado, a carroça do vendedor de óleo.",
  "Light the Deepam": "Acenda o Deepam",
  "Find the golden lamp and run it the whole street back to the temple steps.": "Encontre a lamparina dourada e leve-a correndo por toda a rua até os degraus do templo.",
  "🪔 The golden Deepam lamp is gone! Light a cracker by the dark patch to find the oil drips": "🪔 A lamparina dourada do Deepam sumiu! Acenda um fogo perto do trecho escuro para achar as gotas de óleo",
  "🚨 Seth-ji thinks YOU are the thief! Run the Deepam lamp to the temple steps 🛕": "🚨 O Seth-ji acha que o ladrão é VOCÊ! Leve a lamparina do Deepam correndo até os degraus do templo 🛕",
  "The Deepam lamp is home!": "A lamparina do Deepam voltou para casa!",
